mapper.select:
SELECT 
FROM embedding_chunk
WHERE embedding_config_id = #{embeddingConfigId}
  AND doc_ref_type = #{docRefType}
  AND doc_ref_id = #{docRefId}
ORDER BY chunk_index ASC, id ASC

SELECT pg_advisory_xact_lock(
    hashtextextended(
        CAST(concat(
            'embedding_chunk:', CAST(#{embeddingConfigId} AS text), ':',
            CAST(#{docRefTypeLength} AS text), ':',
            CAST(#{docRefType} AS text), ':', CAST(#{docRefId} AS text)
        ) AS text),
        0
    )
)
